challenge.verificationSource:
mod solution;
fn roundtrip(text: &str) -> String {
    let path = std::path::Path::new(if cfg!(target_arch = "wasm32") { "/sandbox/crabrix-report.txt" } else { "crabrix-report.txt" });
    match std::fs::remove_file(path) {
        Ok(()) => {},
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {},
        Err(error) => panic!("cleanup failed: {error}"),
    }
    let actual = solution::save_report(path, text).unwrap();
    // Observe the effect independently; returning the input is not sufficient.
    assert_eq!(std::fs::read_to_string(path).unwrap(), text);
    actual
}
fn main() {
    assert_eq!(roundtrip("crab: 3\n"), "crab: 3\n", "case 1");
    assert_eq!(roundtrip(""), "", "case 2");
    assert_eq!(roundtrip("Rust 🦀\nnext"), "Rust 🦀\nnext", "case 3");
    let directory = std::path::Path::new(if cfg!(target_arch = "wasm32") { "/sandbox" } else { "." });
    assert!(solution::save_report(directory, "must fail").is_err());
    println!("PASS sandbox-file-roundtrip");
}
